#import "SOReplicantMask.h"

@implementation SOReplicantMask

- (instancetype)initWithParent:(SOScrollerOverlay *)parent{
    self = [super init];
    if (self){
        self.parentOverlay = parent;
        self.contentsScale = 2.0;
        self.needsDisplayOnBoundsChange = YES;
        self.opaque = NO;
        self.hidden = parent.isHidden;
        self.zPosition++;
    }
    return self;
}

- (void)drawInContext:(CGContextRef)ctx {
    SOScrollerOverlay * o = self.parentOverlay;
    if (!o) return;

    CGContextClearRect(ctx, self.bounds);
    
    if (o.orientation == SOScrollOrientationVertical){
        if (!o.isHidden){
            if (!o.middleLayer.isHidden) {
                CGImageRef mid = [self middleMaskForOrientation:SOScrollOrientationVertical];
                if (mid) {
                    CGRect zeroFrame = CGRectMake(-1, o.middleLayer.frame.origin.y, o.middleLayer.bounds.size.width + 2, o.middleLayer.bounds.size.height);
                    CGContextDrawImage(ctx, zeroFrame, mid);
                }
            }

            CGImageRef bot = [self bottomMaskForOrientation:SOScrollOrientationVertical];
            if (bot) {
                CGRect zeroFrame = CGRectMake(-1, o.bottomLayer.frame.origin.y, o.bottomLayer.bounds.size.width + 2, o.bottomLayer.bounds.size.height);
                CGContextDrawImage(ctx, zeroFrame, bot);
            }

            CGImageRef top = [self topMaskForOrientation:SOScrollOrientationVertical];
            if (top) {
                CGRect zeroFrame = CGRectMake(-1, o.topCapLayer.frame.origin.y, o.topCapLayer.bounds.size.width + 2, o.topCapLayer.bounds.size.height);
                CGContextDrawImage(ctx, zeroFrame, top);
            }
        }
    } else {
        if (!o.isHidden){
            if (!o.middleLayer.isHidden) {
                CGImageRef mid = [self middleMaskForOrientation:SOScrollOrientationHorizontal];
                if (mid) {
                    CGRect zeroFrame = CGRectMake(o.middleLayer.frame.origin.x, -1, o.middleLayer.bounds.size.width, o.middleLayer.bounds.size.height + 2);
                    CGContextDrawImage(ctx, zeroFrame, mid);
                }
            }

            CGImageRef bot = [self bottomMaskForOrientation:SOScrollOrientationHorizontal];
            if (bot) {
                CGRect zeroFrame = CGRectMake(o.bottomLayer.frame.origin.x, -1, o.bottomLayer.bounds.size.width, o.bottomLayer.bounds.size.height + 2);
                CGContextDrawImage(ctx, zeroFrame, bot);
            }

            CGImageRef top = [self topMaskForOrientation:SOScrollOrientationHorizontal];
            if (top) {
                CGRect zeroFrame = CGRectMake(o.topCapLayer.frame.origin.x, -1, o.topCapLayer.bounds.size.width, o.topCapLayer.bounds.size.height + 2);
                CGContextDrawImage(ctx, zeroFrame, top);
            }
        }
    }
}

static CGImageRef CreateCGImageFromB64(NSString * b64){
    CGDataProviderRef provider =
    CGDataProviderCreateWithCFData((__bridge CFDataRef)
                                   ([[NSData alloc] initWithBase64EncodedString:b64 options:NSDataBase64DecodingIgnoreUnknownCharacters]));

    if (!provider) return NULL;

    CGImageRef image =
        CGImageCreateWithPNGDataProvider(
            provider,
            NULL,
            NO,
            kCGRenderingIntentDefault);

    CGDataProviderRelease(provider);

    return image;
}

#pragma mark - Resource methods

- (CGImageRef)middleMaskForOrientation:(SOScrollOrientation)orientation {
    static CGImageRef verticalTrack = NULL;
    static CGImageRef horizontalTrack = NULL;
    
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        if (!verticalTrack)
            verticalTrack = CreateCGImageFromB64([self middleLayerForMask]);
        if (!horizontalTrack)
            horizontalTrack = CreateCGImageFromB64([self middleLayerForMaskHorizontal]);
    });
    
    if (orientation == SOScrollOrientationVertical){
        return verticalTrack;
    } else {
        return horizontalTrack;
    }
}

- (CGImageRef)topMaskForOrientation:(SOScrollOrientation)orientation {
    static CGImageRef verticalTrack = NULL;
    static CGImageRef horizontalTrack = NULL;
    
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        if (!verticalTrack)
            verticalTrack = CreateCGImageFromB64([self topLayerForMask]);
        if (!horizontalTrack)
            horizontalTrack = CreateCGImageFromB64([self topLayerForMaskHorizontal]);
    });
    
    if (orientation == SOScrollOrientationVertical){
        return verticalTrack;
    } else {
        return horizontalTrack;
    }
}

- (CGImageRef)bottomMaskForOrientation:(SOScrollOrientation)orientation {
    static CGImageRef verticalTrack = NULL;
    static CGImageRef horizontalTrack = NULL;
    
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        if (!verticalTrack)
            verticalTrack = CreateCGImageFromB64([self bottomLayerForMask]);
        if (!horizontalTrack)
            horizontalTrack = CreateCGImageFromB64([self bottomLayerForMaskHorizontal]);
    });
    
    if (orientation == SOScrollOrientationVertical){
        return verticalTrack;
    } else {
        return horizontalTrack;
    }
}

- (NSString *)middleLayerForMask{
    return @"";
}

- (NSString *)middleLayerForMaskHorizontal{
    return @"";
}

- (NSString *)topLayerForMask{
    return @"";
}

- (NSString *)topLayerForMaskHorizontal{
    return @"";
}

- (NSString *)bottomLayerForMask{
    return @"";
}

- (NSString *)bottomLayerForMaskHorizontal{
    return @"";
}
@end
